-- SYSTEMBOOM SIE V1.2 / REFERENCE ONLY — DO NOT EXECUTE BEFORE P2-A AND OWNER APPROVAL
-- Assumes PostgreSQL and pgcrypto where gen_random_uuid() is available.
CREATE SCHEMA IF NOT EXISTS heim;
CREATE TABLE heim.ai_providers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider_key text NOT NULL UNIQUE, display_name text NOT NULL, endpoint_family text, enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE heim.ai_models (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider_id uuid NOT NULL REFERENCES heim.ai_providers(id), configured_model_key text NOT NULL, published_revision text, capabilities jsonb NOT NULL DEFAULT '{}'::jsonb, enabled boolean NOT NULL DEFAULT true, UNIQUE(provider_id, configured_model_key, published_revision));
CREATE TABLE heim.ai_pricing_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), model_id uuid NOT NULL REFERENCES heim.ai_models(id), price_type text NOT NULL, unit text NOT NULL, unit_price_usd numeric(20,10) NOT NULL CHECK(unit_price_usd>=0), valid_from timestamptz NOT NULL, valid_until timestamptz, source_reference text, CHECK(valid_until IS NULL OR valid_until>valid_from));
CREATE TABLE heim.ai_invocations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_scope_id uuid NOT NULL, request_trace_id text NOT NULL, provider_id uuid REFERENCES heim.ai_providers(id), model_id uuid REFERENCES heim.ai_models(id), requested_provider_key text NOT NULL, requested_model_key text NOT NULL, observed_provider_key text, observed_model_key text, observed_model_verifiable boolean NOT NULL DEFAULT false, task_type text NOT NULL, prompt_id text NOT NULL, prompt_version text NOT NULL, prompt_digest text, schema_version text NOT NULL, preprocessing_version text, classifier_version text, knowledge_version text, policy_version text, status text NOT NULL CHECK(status IN ('started','succeeded','failed','cancelled','unknown')), input_tokens bigint CHECK(input_tokens IS NULL OR input_tokens>=0), output_tokens bigint CHECK(output_tokens IS NULL OR output_tokens>=0), cached_input_tokens bigint CHECK(cached_input_tokens IS NULL OR cached_input_tokens>=0), latency_ms integer CHECK(latency_ms IS NULL OR latency_ms>=0), pricing_version_id uuid REFERENCES heim.ai_pricing_versions(id), estimated_cost_usd numeric(20,10) CHECK(estimated_cost_usd IS NULL OR estimated_cost_usd>=0), started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, CHECK(finished_at IS NULL OR finished_at>=started_at));
CREATE TABLE heim.ai_artifact_provenance (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_scope_id uuid NOT NULL, invocation_id uuid NOT NULL REFERENCES heim.ai_invocations(id), artifact_kind text NOT NULL CHECK(artifact_kind IN ('observation','category_decision','specialist_enrichment','embedding','ocr')), artifact_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(invocation_id,artifact_kind,artifact_id));
CREATE INDEX ON heim.ai_invocations(owner_scope_id,started_at DESC);
CREATE INDEX ON heim.ai_artifact_provenance(owner_scope_id,artifact_kind,artifact_id);
-- Not runnable against production: owner_scope_id must bind to authenticated canonical owner/tenant and RLS/auth policies must be designed.
